const authRbacSql = "-- Auth + RBAC（FastAdmin / BuildAdmin 风格：管理员 / 角色 / 权限节点）\r\n-- 全部 IF NOT EXISTS，本地与部署均可重复执行。\r\n\r\nCREATE TABLE IF NOT EXISTS admins (\r\n  id TEXT PRIMARY KEY NOT NULL,\r\n  username TEXT NOT NULL UNIQUE,\r\n  nickname TEXT NOT NULL DEFAULT '',\r\n  hashed_password TEXT NOT NULL,\r\n  status TEXT NOT NULL DEFAULT 'enabled',\r\n  is_super INTEGER NOT NULL DEFAULT 0,\r\n  last_login_at INTEGER,\r\n  created_at INTEGER NOT NULL\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS admin_sessions (\r\n  id TEXT PRIMARY KEY NOT NULL,\r\n  admin_id TEXT NOT NULL,\r\n  expires_at INTEGER NOT NULL,\r\n  created_at INTEGER NOT NULL,\r\n  FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_admin_sessions_admin ON admin_sessions(admin_id);\r\nCREATE INDEX IF NOT EXISTS idx_admin_sessions_expires ON admin_sessions(expires_at);\r\n\r\nCREATE TABLE IF NOT EXISTS auth_roles (\r\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\r\n  name TEXT NOT NULL UNIQUE,\r\n  description TEXT NOT NULL DEFAULT '',\r\n  status TEXT NOT NULL DEFAULT 'enabled',\r\n  sort INTEGER NOT NULL DEFAULT 0,\r\n  created_at INTEGER NOT NULL\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS auth_rules (\r\n  id INTEGER PRIMARY KEY AUTOINCREMENT,\r\n  parent_id INTEGER NOT NULL DEFAULT 0,\r\n  name TEXT NOT NULL UNIQUE,\r\n  title TEXT NOT NULL,\r\n  type TEXT NOT NULL DEFAULT 'menu',\r\n  path TEXT NOT NULL DEFAULT '',\r\n  icon TEXT NOT NULL DEFAULT '',\r\n  sort INTEGER NOT NULL DEFAULT 0,\r\n  status TEXT NOT NULL DEFAULT 'enabled',\r\n  created_at INTEGER NOT NULL\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS admin_roles (\r\n  admin_id TEXT NOT NULL,\r\n  role_id INTEGER NOT NULL,\r\n  PRIMARY KEY (admin_id, role_id),\r\n  FOREIGN KEY (admin_id) REFERENCES admins(id) ON DELETE CASCADE,\r\n  FOREIGN KEY (role_id) REFERENCES auth_roles(id) ON DELETE CASCADE\r\n);\r\n\r\nCREATE TABLE IF NOT EXISTS role_rules (\r\n  role_id INTEGER NOT NULL,\r\n  rule_id INTEGER NOT NULL,\r\n  PRIMARY KEY (role_id, rule_id),\r\n  FOREIGN KEY (role_id) REFERENCES auth_roles(id) ON DELETE CASCADE,\r\n  FOREIGN KEY (rule_id) REFERENCES auth_rules(id) ON DELETE CASCADE\r\n);\r\n";
const modelsSql = "-- 模型（图纸）/ 集合（房子）/ 实体（内容行）\n-- CREATE 已含 group_id / locale / language_group_key；旧库由 0007 / COLUMN_PATCHES 补齐\n\nCREATE TABLE IF NOT EXISTS models (\n  id TEXT PRIMARY KEY NOT NULL,\n  name TEXT NOT NULL,\n  slug TEXT NOT NULL UNIQUE,\n  description TEXT NOT NULL DEFAULT '',\n  fields_json TEXT NOT NULL DEFAULT '[]',\n  version INTEGER NOT NULL DEFAULT 1,\n  status TEXT NOT NULL DEFAULT 'enabled',\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL\n);\n\nCREATE INDEX IF NOT EXISTS idx_models_status ON models(status);\n\nCREATE TABLE IF NOT EXISTS collections (\n  id TEXT PRIMARY KEY NOT NULL,\n  model_id TEXT NOT NULL,\n  group_id TEXT,\n  name TEXT NOT NULL,\n  slug TEXT NOT NULL UNIQUE,\n  description TEXT NOT NULL DEFAULT '',\n  icon TEXT NOT NULL DEFAULT 'DatabaseOutlined',\n  sort INTEGER NOT NULL DEFAULT 0,\n  field_config TEXT NOT NULL DEFAULT '{}',\n  status TEXT NOT NULL DEFAULT 'enabled',\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  FOREIGN KEY (model_id) REFERENCES models(id)\n);\n\nCREATE INDEX IF NOT EXISTS idx_collections_model ON collections(model_id);\nCREATE INDEX IF NOT EXISTS idx_collections_status ON collections(status);\n\nCREATE TABLE IF NOT EXISTS entities (\n  id TEXT PRIMARY KEY NOT NULL,\n  collection_id TEXT NOT NULL,\n  data_json TEXT NOT NULL DEFAULT '{}',\n  locale TEXT NOT NULL DEFAULT 'zh-CN',\n  language_group_key TEXT,\n  created_by TEXT,\n  created_at INTEGER NOT NULL,\n  updated_at INTEGER NOT NULL,\n  FOREIGN KEY (collection_id) REFERENCES collections(id) ON DELETE CASCADE\n);\n\nCREATE INDEX IF NOT EXISTS idx_entities_collection ON entities(collection_id);\n";
const sitesSql = "-- 站点域名 / 主机策略（第二期公开 API 的前置骨架）\r\n\r\nCREATE TABLE IF NOT EXISTS site_settings (\r\n  key TEXT PRIMARY KEY NOT NULL,\r\n  value_json TEXT NOT NULL DEFAULT '{}',\r\n  updated_at INTEGER NOT NULL\r\n);\r\n";
const navGroupsSql = "-- 真实导航分组（递归树）+ 集合挂组\r\n-- 顶层分组自然形成「站点」语义前缀；本阶段不做 API 路径派生\r\n\r\nCREATE TABLE IF NOT EXISTS nav_groups (\r\n  id TEXT PRIMARY KEY NOT NULL,\r\n  parent_id TEXT,\r\n  name TEXT NOT NULL,\r\n  slug TEXT NOT NULL,\r\n  icon TEXT NOT NULL DEFAULT 'FolderOutlined',\r\n  sort INTEGER NOT NULL DEFAULT 0,\r\n  status TEXT NOT NULL DEFAULT 'enabled',\r\n  created_at INTEGER NOT NULL,\r\n  updated_at INTEGER NOT NULL,\r\n  FOREIGN KEY (parent_id) REFERENCES nav_groups(id)\r\n);\r\n\r\nCREATE INDEX IF NOT EXISTS idx_nav_groups_parent ON nav_groups(parent_id);\r\nCREATE INDEX IF NOT EXISTS idx_nav_groups_status ON nav_groups(status);\r\n";
