async function securityHeadersMiddleware(c, next2) {
  await next2();
  const original = c.res;
  const headers = new Headers(original.headers);
  if (!headers.get("X-Content-Type-Options")) {
    headers.set("X-Content-Type-Options", "nosniff");
  }
  if (!headers.get("X-Frame-Options")) {
    headers.set("X-Frame-Options", "SAMEORIGIN");
  }
  if (!headers.get("Referrer-Policy")) {
    headers.set("Referrer-Policy", "strict-origin-when-cross-origin");
  }
  if (!headers.get("Permissions-Policy")) {
    headers.set("Permissions-Policy", "camera=(), microphone=(), geolocation=()");
  }
  const production = resolveRuntimeMode(c.env) === "production";
  const url = new URL(c.req.url);
  if (production && url.protocol === "https:" && !headers.get("Strict-Transport-Security")) {
    headers.set("Strict-Transport-Security", "max-age=31536000; includeSubDomains");
  }
  c.res = new Response(original.body, {
    status: original.status,
    statusText: original.statusText,
    headers
  });
}
