app.all("*", async (c) => {
  const hostTarget = c.get("hostTarget");
  if (hostTarget === "api") {
    return c.json({ error: "Not Found" }, 404);
  }
  const url = new URL(c.req.url);
  if (hostTarget === "member" && (url.pathname === "/" || url.pathname === "")) {
    url.pathname = "/member";
    return c.redirect(url.toString(), 302);
  }
  if (!c.env.ASSETS) {
    return c.json({ error: "静态资源未绑定（ASSETS）" }, 500, {
      "Cache-Control": "private, no-store"
    });
  }
  try {
    const asset = await c.env.ASSETS.fetch(c.req.raw);
    if (asset.status < 500 && asset.status !== 404) return asset;
    if (c.req.method !== "GET" && c.req.method !== "HEAD") {
      if (asset.status < 500) return asset;
      throw new Error(`静态资源读取失败（HTTP ${asset.status}）`);
    }
    const indexed = await c.env.ASSETS.fetch(
      new Request(new URL("/index.html", c.req.url), c.req.raw)
    );
    if (indexed.status < 500 && indexed.status !== 404) return indexed;
    throw new Error(
      `静态资源不可用（HTTP ${indexed.status || asset.status}）。请确认 vite build 后通过产物 wrangler.json 部署（assets 应为 dist/client/client）`
    );
  } catch (err) {
    if (err instanceof Error && err.message.includes("静态资源")) throw err;
    const detail = err instanceof Error ? err.message : String(err);
    throw new Error(`静态资源读取失败: ${detail}`);
  }
});
